class Solution:
    ONES = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
            "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen",
            "Eighteen", "Nineteen"]
    TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
    SCALES = ["", "Thousand", "Million", "Billion"]

    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"

        def chunk(n: int) -> List[str]:               # words for 0 <= n < 1000
            words = []
            if n >= 100:
                words += [self.ONES[n // 100], "Hundred"]
                n %= 100
            if n >= 20:
                words.append(self.TENS[n // 10])
                n %= 10
            if n:                                     # 1..19 (teens are one word)
                words.append(self.ONES[n])
            return words

        out = []
        for scale in self.SCALES:                     # peel 3 digits at a time, low to high
            if num % 1000:
                out = chunk(num % 1000) + ([scale] if scale else []) + out
            num //= 1000
        return " ".join(out)

class Solution:
    def shortestPalindrome(self, s: str) -> str:
        t = s + "#" + s[::-1]                         # '#' stops a border crossing the middle
        fail = [0] * len(t)                           # fail[i] = longest proper border of t[:i+1]
        for i in range(1, len(t)):
            k = fail[i - 1]
            while k and t[i] != t[k]:                 # fall back along shorter borders
                k = fail[k - 1]
            if t[i] == t[k]:
                k += 1
            fail[i] = k
        keep = fail[-1]                               # longest palindromic prefix of s
        return s[keep:][::-1] + s

