        stack = [-1]                                 # indices; stack[0] is the barrier
        best = 0
        for i, c in enumerate(s):
            if c == "(":
                stack.append(i)
            elif len(stack) > 1:                     # an open "(" is waiting: match it
                stack.pop()
                best = max(best, i - stack[-1])      # run extends back to the new top
