def brute_force(nums1: List[int], nums2: List[int], k: int) -> List[int]:
    def interleave(a, b):                                   # every order-preserving merge
        if not a or not b:
            yield a + b
            return
        for rest in interleave(a[1:], b):
            yield [a[0]] + rest
        for rest in interleave(a, b[1:]):
            yield [b[0]] + rest

    best = []
    for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
        for ca in combinations(nums1, i):                   # exponential: 2^m * 2^n * C(k, i)
            for cb in combinations(nums2, k - i):
                for merged in interleave(list(ca), list(cb)):
                    best = max(best, merged)
    return best

class BruteForce:
    """Plain list in push order; pop recounts everything and scans from the top, O(n)."""

    def __init__(self):
        self.items = []

    def push(self, val: int) -> None:
        self.items.append(val)

    def pop(self) -> int:
        counts = Counter(self.items)             # rebuilt from scratch on every pop
        top = max(counts.values())
        for i in range(len(self.items) - 1, -1, -1):
            if counts[self.items[i]] == top:     # rightmost among the most frequent
                return self.items.pop(i)

